<script setup>
import {computed,ref} from "vue";import {ShoppingCart} from "@lucide/vue";import AdminLayout from "../components/admin/AdminLayout.vue";import AsyncButton from "../components/AsyncButton.vue";import DataTable from "../components/DataTable.vue";import SelectInput from "../components/SelectInput.vue";import {apiFetch} from "../services/api";import {useAuth} from "../services/auth";import {useServerTable} from "../services/serverTable";import {toast} from "../services/toast";import {t} from "../services/i18n";
const recommendations=ref([]),suppliers=ref([]),days=ref(7),creating=ref(false);const{can}=useAuth();const{items,loading,pagination,load}=useServerTable({endpoint:"/api/v1/admin/inventory",collectionKey:"inventory",onResponse:r=>{recommendations.value=r.recommendations||[];suppliers.value=r.suppliers||[]}});const columns=computed(()=>[{key:"name",label:t("products.name")},{key:"sku",label:t("products.sku")},{key:"category_name",label:t("products.category"),sortable:false},{key:"current_stock",label:t("stock.current")},{key:"minimum_stock",label:t("stock.minimum")},{key:"stock_status",label:t("stock.status"),sortable:false}]);const statusClass=s=>s==="available"?"bg-brand-50 text-brand-600":s==="low"?"bg-warning-50 text-warning-700":"bg-error-50 text-error-600";async function reloadDays(value){days.value=value;await load({days:value})}async function setSupplier(row,value){try{await apiFetch(`/api/v1/admin/inventory/${row.id}/preferred_supplier`,{method:"PATCH",body:JSON.stringify({supplier_id:value})});row.preferred_supplier_id=value;row.preferred_supplier_name=suppliers.value.find(x=>String(x.id)===String(value))?.name||null}catch(e){toast.error(e.message)}}async function createDrafts(){creating.value=true;try{const r=await apiFetch("/api/v1/admin/inventory/create_drafts",{method:"POST",body:JSON.stringify({product_ids:recommendations.value.map(x=>x.id),days:days.value})});toast.success(t("stock.drafts_created",{count:r.purchase_orders.length}));window.location.assign("/admin/purchases")}catch(e){toast.error(e.message)}finally{creating.value=false}}
</script>
<template><AdminLayout><div class="mx-auto max-w-[1536px]"><div class="mb-6"><h1 class="text-2xl font-semibold dark:text-white">{{t('stock.inventory_title')}}</h1><p class="mt-1 text-sm text-gray-500">{{t('stock.inventory_subtitle')}}</p></div><section v-if="recommendations.length" class="mb-6 rounded-2xl border border-warning-200 bg-warning-50/50 p-5 dark:bg-gray-900"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-semibold">{{t('stock.restock_title')}}</h2><p class="text-sm text-gray-500">{{t('stock.restock_hint')}}</p></div><div class="flex gap-2"><button v-for="value in [7,30]" :key="value" class="rounded-lg border px-3 py-2 text-sm" :class="days===value?'bg-brand-500 text-white':''" @click="reloadDays(value)">{{value}} {{t('stock.days')}}</button></div></div><div class="mt-4 divide-y rounded-xl border bg-white dark:bg-gray-900"><div v-for="row in recommendations" :key="row.id" class="grid items-center gap-3 p-3 md:grid-cols-[1fr_130px_160px_220px]"><div><strong>{{row.name}}</strong><small class="block text-gray-500">{{row.sku}} · {{t('stock.average_daily')}} {{row.average_daily_sales}}</small></div><span>{{t('stock.current')}}: <b>{{row.current_stock}}</b></span><span>{{t('stock.recommend')}}: <b class="text-brand-600">+{{row.recommended_quantity}}</b></span><SelectInput :model-value="row.preferred_supplier_id||''" @update:model-value="setSupplier(row,$event)"><option value="">{{t('stock.select_supplier')}}</option><option v-for="supplier in suppliers" :key="supplier.id" :value="supplier.id">{{supplier.name}}</option></SelectInput></div></div><AsyncButton v-if="can('purchases.create')" :loading="creating" :disabled="recommendations.some(x=>!x.preferred_supplier_id)" class="mt-4 rounded-lg bg-brand-500 px-4 py-2.5 text-white" @click="createDrafts"><ShoppingCart :size="17"/>{{t('stock.create_purchase')}}</AsyncButton></section><DataTable :items="items" :columns="columns" :loading="loading" :empty-text="t('stock.empty')" server-mode :total="pagination.total" @request="load"><template #cell-name="{item}"><strong class="dark:text-white">{{item.name}}</strong></template><template #cell-current_stock="{item}">{{item.current_stock}} {{item.unit}}</template><template #cell-minimum_stock="{item}">{{item.minimum_stock}} {{item.unit}}</template><template #cell-stock_status="{item}"><span :class="statusClass(item.stock_status)" class="rounded-full px-2.5 py-1 text-xs font-medium">{{t(`stock.${item.stock_status}`)}}</span></template></DataTable></div></AdminLayout></template>
